303	                if (!proactive.fileSystem.read.includes(cwd)) {
304	                  proactive.fileSystem.read.push(cwd);
305	                }
306	              }
307	            }
308	
309	            const isApproved = (
310	              requestedPath: string,
311	              approvedPaths?: string[],
312	            ): boolean => {
