121	): Promise<void> {
122	  const currentMode = context.config.getApprovalMode();
123	
124	  // Mode Transitions (AUTO_EDIT)
125	  if (isAutoEditTransition(tool, outcome)) {
126	    context.config.setApprovalMode(ApprovalMode.AUTO_EDIT);
127	  }
128	
129	  // Determine persist scope if we are persisting.
130	  let persistScope: 'workspace' | 'user' | undefined;
131	  let modes: ApprovalMode[] | undefined;
132	
133	  // If this is an 'Always Allow' selection, we restrict it to the current mode
134	  // and more permissive modes.
135	  if (
136	    outcome === ToolConfirmationOutcome.ProceedAlways ||
137	    outcome === ToolConfirmationOutcome.ProceedAlwaysTool ||
138	    outcome === ToolConfirmationOutcome.ProceedAlwaysServer ||
139	    outcome === ToolConfirmationOutcome.ProceedAlwaysAndSave
140	  ) {
141	    const modeIndex = MODES_BY_PERMISSIVENESS.indexOf(currentMode);
142	    if (modeIndex !== -1) {
143	      modes = MODES_BY_PERMISSIVENESS.slice(modeIndex);
144	    }
145	  }
146	
147	  if (outcome === ToolConfirmationOutcome.ProceedAlwaysAndSave) {
148	    // If folder is trusted and workspace policies are enabled, we prefer workspace scope.
149	    if (
150	      context.config &&
151	      context.config.isTrustedFolder() &&
152	      context.config.getWorkspacePoliciesDir() !== undefined
153	    ) {
154	      persistScope = 'workspace';
155	    } else {
156	      persistScope = 'user';
157	    }
158	  }
159	
160	  // Specialized Tools (MCP)
161	  if (confirmationDetails?.type === 'mcp') {
162	    await handleMcpPolicyUpdate(
163	      tool,
164	      outcome,
165	      confirmationDetails,
166	      messageBus,
167	      persistScope,
168	      modes,
169	    );
170	    return;
171	  }
172	
173	  // Generic Fallback (Shell, Info, etc.)
174	  await handleStandardPolicyUpdate(
175	    tool,
176	    outcome,
177	    confirmationDetails,
178	    messageBus,
179	    persistScope,
180	    toolInvocation,
181	    context.config,
182	    modes,
183	  );
184	}
