188	 * should trigger a session-wide transition to AUTO_EDIT mode.
189	 */
190	function isAutoEditTransition(
191	  tool: AnyDeclarativeTool,
192	  outcome: ToolConfirmationOutcome,
193	): boolean {
194	  // TODO: This is a temporary fix to enable AUTO_EDIT mode for specific
195	  // tools. We should refactor this so that callbacks can be removed from
196	  // tools.
197	  return (
198	    outcome === ToolConfirmationOutcome.ProceedAlways &&
199	    EDIT_TOOL_NAMES.has(tool.name)
200	  );
201	}
