53	export async function checkPolicy(
54	  toolCall: ValidatingToolCall,
55	  config: Config,
56	  subagent?: string,
57	): Promise<CheckResult> {
58	  const serverName =
59	    toolCall.tool instanceof DiscoveredMCPTool
60	      ? toolCall.tool.serverName
61	      : undefined;
62	
63	  const toolAnnotations = toolCall.tool.toolAnnotations;
64	
65	  const result = await config
66	    .getPolicyEngine()
67	    .check(
68	      { name: toolCall.request.name, args: toolCall.request.args },
69	      serverName,
70	      toolAnnotations,
71	      subagent,
72	    );
73	
74	  const { decision } = result;
75	
76	  // If the tool call was initiated by the client (e.g. via a slash command),
77	  // we treat it as implicitly confirmed by the user and bypass the
78	  // confirmation prompt if the policy engine's decision is 'ASK_USER'.
79	  if (
80	    decision === PolicyDecision.ASK_USER &&
81	    toolCall.request.isClientInitiated &&
82	    !toolCall.request.args?.['additional_permissions']
